#!/usr/bin/env python3
"""
Applique le deploy.yml v2 avec recherche automatique du dossier de sortie Roq.
À exécuter depuis la racine du dépôt dans le Codespace.
"""
import base64, pathlib

DEPLOY_YML = ""

p = pathlib.Path(".github/workflows/deploy.yml")
p.parent.mkdir(parents=True, exist_ok=True)
p.write_bytes(base64.b64decode(DEPLOY_YML))
print("✅  .github/workflows/deploy.yml")
print()
print("Commandes git à exécuter :")
print("  git add .github/workflows/deploy.yml")
print('  git commit -m "ci: debug roq output dir + flexible s3 sync"')
print("  git push")
